import logo from './logo.svg';
import './App.css';
import LightPillar from './LightPillar';

function App() {
  return (
    <div className="App">
      <header className="App-header">

      </header>

      <div style={{ width: '100%', height: '600px', position: 'relative' }}>
        <LightPillar
          topColor="#ce466f"
          bottomColor="#04060e"
          intensity={1}
          rotationSpeed={0.3}
          glowAmount={0.002}
          pillarWidth={3}
          pillarHeight={0.4}
          noiseIntensity={0.5}
          pillarRotation={25}
          interactive={false}
          mixBlendMode="screen"
          quality="high"
        />
      </div>
    </div>
  );
}

export default App;
